'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  InsufficientStockError,
  UnknownSkuError,
  ValidationError,
  OrderStateError
} = require('../src');

async function service(stock = { widget: 10 }) {
  const svc = new InventoryService();
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

test('addStock creates and tops up a sku', async () => {
  const svc = new InventoryService();
  assert.deepEqual(await svc.addStock('widget', 5), { sku: 'widget', stock: 5, reserved: 0, sold: 0 });
  assert.deepEqual(await svc.addStock('widget', 2), { sku: 'widget', stock: 7, reserved: 0, sold: 0 });
});

test('reserve holds stock and commit sells it', async () => {
  const svc = await service();
  const reservation = await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  assert.deepEqual(reservation, { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 3 }] });
'use strict';

// In-memory key-value store with the latency profile of the Redis cluster
// used in production: every call yields to the event loop before it reads or
// writes, so concurrent callers interleave the way they do against the real
// store. Values are copied on the way in and out.
class Store {
  constructor() {
    this.data = new Map();
  }

  async get(key) {
    await tick();
    const value = this.data.get(key);
    return value === undefined ? undefined : structuredClone(value);
  }

  async set(key, value) {
    await tick();
    this.data.set(key, structuredClone(value));
  }

  async keys(prefix) {
    await tick();
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

module.exports = { Store };

